import os
import re

PATTERNS = {
    "antigravity": re.compile(r"antigravity", re.IGNORECASE),
    "gemini": re.compile(r"gemini", re.IGNORECASE),
    "copilot_chatgpt": re.compile(r"(copilot|chatgpt|openai|claude)", re.IGNORECASE),
    "ai_generated": re.compile(r"(ai-generated|generated by ai|ai assistant|coding agent)", re.IGNORECASE),
    "todo_fixme": re.compile(r"\b(TODO|FIXME|XXX|HACK)\b"),
    "prompts_or_phases": re.compile(r"(phase\s*\d|step\s*\d|task\s*\d|prompt\s*\d|user request)", re.IGNORECASE),
    "stubs_or_mocks": re.compile(r"\b(stub|dummy|mock)\b", re.IGNORECASE),
}

EXCLUDE_DIRS = {".git", ".venv", "__pycache__", ".pytest_cache", "dist", "build", ".vanta_data", "node_modules"}

results = {k: [] for k in PATTERNS}

for root, dirs, files in os.walk("."):
    dirs[:] = [d for d in dirs if d not in EXCLUDE_DIRS]
    for file in files:
        if file.endswith((".pyc", ".exe", ".png", ".ico", ".webm", ".bin")):
            continue
        rel_path = os.path.relpath(os.path.join(root, file), ".")
        if "audit_codebase.py" in rel_path or "verify_bundle.py" in rel_path:
            continue
        try:
            with open(rel_path, "r", encoding="utf-8", errors="ignore") as f:
                for line_no, line in enumerate(f, 1):
                    for pat_name, pat_re in PATTERNS.items():
                        m = pat_re.search(line)
                        if m:
                            results[pat_name].append((rel_path, line_no, line.strip()))
        except Exception as e:
            pass

print("=== CODEBASE AUDIT RESULTS ===")
for pat_name, matches in results.items():
    print(f"\n--- {pat_name.upper()} ({len(matches)} matches) ---")
    for path, line_no, text in matches[:25]:
        safe_text = text.encode("ascii", "replace").decode("ascii")[:100]
        print(f"  {path}:{line_no} -> {safe_text}")
    if len(matches) > 25:
        print(f"  ... and {len(matches) - 25} more.")
